To implement the 2D alpha shape, we need to find the set of edges and triangles from the Delaunay triangulation that satisfy the alpha criterion. An edge is part of the alpha shape if there exists a circle of radius $\alpha$ that passes through its endpoints and contains no other points. A triangle is part of the alpha shape if its circumradius is less than $\alpha$.

The "solid components" typically refer to the connected components of the resulting alpha complex.

```cpp
    if (points.empty()) return 0;
    if (points.size() < 3) return points.empty() ? 0 : 1;

    // Use CGAL for Delaunay Triangulation
    typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
    typedef CGAL::Delaunay_triangulation_2<K> Delaunay;
    typedef K::Point_2 Point_2;

    std::vector<Point_2> cgal_points;
    cgal_points.reserve(points.size());
    for (const auto& p : points) {
        cgal_points.emplace_back(p.x(), p.y());
    }

    Delaunay dt;
    dt.insert(cgal_points.begin(), cgal_points.end());

    // We identify edges that are "alpha-exposed"
    // An edge is in the alpha-shape if it's part of a triangle with circumradius < alpha
    // or if it's an edge of the convex hull and its "empty" circle radius < alpha.

    std::vector<std::pair<int, int>> alpha_edges;
    std::unordered_map<Delaunay::Vertex_handle, int> vertex_to_id;
    int v_count = 0;
    for (auto vit = dt.finite_vertices_begin(); vit != dt.finite_vertices_end(); ++vit) {
        vertex_to_id[*vit] = v_count++;
    }

    for (auto fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit) {
        Point_2 p1 = fit->vertex(0)->point();
        Point_2 p2 = fit->vertex(1)->point();
        Point_2 p3 = fit->vertex(2)->point();

        // Calculate circumradius
        double a = std::sqrt(CGAL::squared_distance(p1, p2));
        double b = std::sqrt(CGAL::squared_distance(p2, p3));
        double c = std::sqrt(CGAL::squared_distance(p3, p1));
        double s = (a + b + c) / 2.0;
        double area = std::sqrt(s * (s - a) * (s - b) * (s - c));

        if (area > 0) {
            double circumradius = (a * b * c) / (4.0 * area);
            if (circumradius < alpha) {
                int id0 = vertex_to_id[fit->vertex(0)];
                int id1 = vertex_to_id[fit->vertex(1)];
                int id2 = vertex_to_id[fit->vertex(2)];
                alpha_edges.push_back({std::min(id0, id1), std::max(id0, id1)});
                alpha_edges.push_back({std::min(id1, id2), std::max(id1, id2)});
                alpha_edges.push_back({std::min(id2, id0), std::max(id2, id0)});
            }
        }
    }

    // Count connected components using Disjoint Set Union (DSU)
    std::vector<int> parent(points.size());
    for (int i = 0; i < (int)points.size(); ++i) parent[i] = i;

    auto find = [&](auto self, int i) -> int {
        return (parent[i] == i) ? i : (parent[i] = self(self, parent[i]));
    };

    auto unite = [&](int i, int j) {
        int root_i = find(find, i);
        int root_j = find(find, j);
        if (root_i != root_j) parent[root_i] = root_j;
    };

    for (const auto& edge : alpha_edges) {
        unite(edge.first, edge.second);
    }

    int components = 0;
    for (int i = 0; i < (int)points.size(); ++i) {
        if (parent[i] == i) components++;
    }

    return components;
